import 'package:flutter/material.dart';import 'glass_card.dart';class GlowIconButton extends StatelessWidget{final IconData icon;final Color color;final VoidCallback? onPressed;final double size;const GlowIconButton({super.key,required this.icon,this.color=Colors.white,this.onPressed,this.size=54});@override Widget build(BuildContext c)=>GlassCard(radius:size/2,padding:EdgeInsets.zero,glowColor:color,onTap:onPressed,child:SizedBox(width:size,height:size,child:Icon(icon,color:color,size:size*.45)));}